fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Check that all vectors have the same length
    let len = dst.len();
    assert_eq!(src.len(), len, "src must have the same length as dst");
    assert_eq!(mask.len(), len, "mask must have the same length as dst");
    
    // Create a new vector to store the result
    let mut result = Vec::with_capacity(len);
    
    // Iterate through all indices
    for i in 0..len {
        if mask[i] {
            // If mask is true, take from src
            result.push(src[i]);
        } else {
            // If mask is false, take from dst
            result.push(dst[i]);
        }
    }
    
    result
}